SELECT NOTICE_ID, TITLE, IMPORTANT, STATUS, VIEW_COUNT, CREATED_ID, CREATED_NICKNAME, TO_CHAR(CREATED_DT, 'YYYY-MM-DD HH24:MI:SS') AS CREATED_DT, UPDATED_ID, TO_CHAR(UPDATED_DT, 'YYYY-MM-DD HH24:MI:SS') AS UPDATED_DT FROM ( SELECT N.NOTICE_ID, N.TITLE, N.IMPORTANT, N.STATUS, N.VIEW_COUNT, N.CREATED_ID, M.NICKNAME AS CREATED_NICKNAME, N.CREATED_DT, N.UPDATED_ID, N.UPDATED_DT, ROW_NUMBER() OVER ( ORDER BY N.IMPORTANT DESC, N.NOTICE_ID DESC ) AS RN FROM NOTICE N LEFT JOIN MEMBER M ON M.MEMBER_ID = N.CREATED_ID
N.TITLE LIKE '%' || #{searchWord} || '%'
AND N.STATUS = #{status}
AND N.IMPORTANT = #{important}
) WHERE RN BETWEEN (#{offset} + 1) AND (#{offset} + #{pageSize}) ORDER BY RN

SELECT COUNT(*)
FROM NOTICE



        TITLE LIKE '%' || #{searchWord} || '%'



        AND STATUS = #{status}



        AND IMPORTANT = #{important}
